// Phase 3 (INTER), INTERINTRA DECODE + PREDICT/BLEND. Two parts:
//
// (A) ENTROPY (the decisive new piece): a REAL single-ref (REFERENCE_MODE
//     SINGLE) frame whose seq enables interintra compound and where the encoder
//     chose interintra for one or more blocks. HarborInterFrameWalk reads the
//     new interintra symbols (flag, mode, wedge flag, wedge index) after the MV
//     resolves and before motion_mode, and must stay od_ec-bit-exact vs the SW
//     reference symbol-by-symbol to frame end. Two frames of the libaom-3.12.1
//     clip (aomenc --enable-interintra-comp=1, cq50, 64x64):
//       * frame 2: 1 smooth interintra block (II_V_PRED, wedge flag read == 0).
//       * frame 9: 3 interintra blocks incl. two WEDGE ones (II_V / II_SMOOTH,
//         wedge indices 8 and 4) - exercises the full wedge flag + wedge index.
//
// (B) PREDICT + BLEND (composition): the HW intra predictor (HarborIntraPred)
//     run over the inter block, blended with the inter prediction through the
//     interintra mask (smooth ramp HarborMaskBlend.interIntraMask or wedge
//     HarborWedgeMask) via HarborMaskBlend, compared bit-exact vs the SW
//     reference blend math on 8x8 / 16x16 luma blocks.

// Per-frame goldens captured from the SW reference decode: the od_ec trace rows
// [tellBefore, rngIn, nsyms, sym, rngAfter, tag] and the SW-derived HW inputs
// (adapted CDFs, header flags, tile bytes, TMVP motion field) packed as the DUT
// consumes them.
class _FrameCap {
  final List<List<int>> gTrace;
  final int allowHp,
      forceInt,
      txModeSel,
      skipModePresent,
      refModeSelect,
      skipRef0,
      skipRef1,
      maskedEn,
      mmSwitch,
      allowWarp,
      enableII,
      signBias,
      useRefMvs;
  final String bytesIn,
      nsymsIn,
      cdfIn,
      tplValid,
      tplRow,
      tplCol,
      tplOff,
      curOff;
  const _FrameCap({
    required this.gTrace,
    required this.allowHp,
    required this.forceInt,
    required this.txModeSel,
    required this.skipModePresent,
    required this.refModeSelect,
    required this.skipRef0,
    required this.skipRef1,
    required this.maskedEn,
    required this.mmSwitch,
    required this.allowWarp,
    required this.enableII,
    required this.signBias,
    required this.useRefMvs,
    required this.bytesIn,
    required this.nsymsIn,
    required this.cdfIn,
    required this.tplValid,
    required this.tplRow,
    required this.tplCol,
    required this.tplOff,
    required this.curOff,
  });
}

