/// One traced HW decode of an interintra frame vs the SW reference. Returns
/// nothing (asserts inside). [expII] is the list of expected interintra blocks
/// as [r, c, bs, mode, useWedge, wedgeIdx].
Future<void> runInterIntraFrame({
  required int target,
  required int expSyms,
  required int expRng,
  required int maxBytes,
  required List<int> txCoeffSizes,
  required List<List<int>> expII,
  required _FrameCap cap,
}) async {
  final gTrace = cap.gTrace;

  const ms = HarborInterFrameWalk.maxSyms;
  const nctx = HarborInterFrameWalk.numCtx;

  final t = HarborInterFrameWalk(
    maxBytes: maxBytes,
    txCoeffSizes: txCoeffSizes,
    enableTmvp: true,
  );
  final clk = SimpleClockGenerator(10).clk;
  final reset = Logic(name: 'reset');
  final start = Logic(name: 'start');
  final bytes = Logic(name: 'bytes', width: maxBytes * 8);
  final allowHp = Logic(name: 'allow_hp');
  final forceInt = Logic(name: 'force_int');
  final txModeSel = Logic(name: 'tx_mode_select');
  final skipModePresent = Logic(name: 'skip_mode_present');
  final refModeSelect = Logic(name: 'ref_mode_select');
  final skipRef0 = Logic(name: 'skip_ref0', width: 3);
  final skipRef1 = Logic(name: 'skip_ref1', width: 3);
  final maskedEn = Logic(name: 'enable_masked_compound');
  final mmSwitch = Logic(name: 'mm_switchable');
  final allowWarp = Logic(name: 'allow_warped_motion');
  final enableII = Logic(name: 'enable_interintra');
  final signBias = Logic(name: 'sign_bias', width: 8);
  final cdfIn = Logic(name: 'cdf_in', width: nctx * ms * 16);
  final nsymsIn = Logic(name: 'nsyms_in', width: nctx * 5);
  final useRefMvs = Logic(name: 'use_ref_frame_mvs');
  final tplValid = Logic(name: 'tpl_valid', width: 64);
  final tplMvRow = Logic(name: 'tpl_mvrow', width: 64 * 16);
  final tplMvCol = Logic(name: 'tpl_mvcol', width: 64 * 16);
  final tplRefOff = Logic(name: 'tpl_refoff', width: 64 * 6);
  final curOff = Logic(name: 'cur_off', width: 7 * 8);

  void conn(String p, Logic s) => t.input(p).srcConnection! <= s;
  conn('clk', clk);
  conn('reset', reset);
  conn('start', start);
  conn('bytes', bytes);
  conn('allow_hp', allowHp);
  conn('force_integer_mv', forceInt);
  conn('tx_mode_select', txModeSel);
  conn('skip_mode_present', skipModePresent);
  conn('ref_mode_select', refModeSelect);
  conn('skip_ref0', skipRef0);
  conn('skip_ref1', skipRef1);
  conn('enable_masked_compound', maskedEn);
  conn('mm_switchable', mmSwitch);
  conn('allow_warped_motion', allowWarp);
  conn('enable_interintra', enableII);
  conn('sign_bias', signBias);
  conn('cdf_in', cdfIn);
  conn('nsyms_in', nsymsIn);
  conn('use_ref_frame_mvs', useRefMvs);
  conn('tpl_valid', tplValid);
  conn('tpl_mvrow', tplMvRow);
  conn('tpl_mvcol', tplMvCol);
  conn('tpl_refoff', tplRefOff);
  conn('cur_off', curOff);
  await t.build();

  reset.inject(1);
  start.inject(0);
  bytes.inject(BigInt.parse(cap.bytesIn));
  allowHp.inject(cap.allowHp);
  forceInt.inject(cap.forceInt);
  txModeSel.inject(cap.txModeSel);
  skipModePresent.inject(cap.skipModePresent);
  refModeSelect.inject(cap.refModeSelect);
  skipRef0.inject(cap.skipRef0);
  skipRef1.inject(cap.skipRef1);
  maskedEn.inject(cap.maskedEn);
  mmSwitch.inject(cap.mmSwitch);
  allowWarp.inject(cap.allowWarp);
  enableII.inject(cap.enableII);
  signBias.inject(cap.signBias);
  cdfIn.inject(BigInt.parse(cap.cdfIn));
  nsymsIn.inject(BigInt.parse(cap.nsymsIn));
  useRefMvs.inject(cap.useRefMvs);
  tplValid.inject(BigInt.parse(cap.tplValid));
  tplMvRow.inject(BigInt.parse(cap.tplRow));
  tplMvCol.inject(BigInt.parse(cap.tplCol));
  tplRefOff.inject(BigInt.parse(cap.tplOff));
  curOff.inject(BigInt.parse(cap.curOff));

  Simulator.setMaxSimTime(4000000000);
  unawaited(Simulator.run());
  await clk.nextPosedge;
  reset.inject(0);
  await clk.nextPosedge;
  start.inject(1);
  await clk.nextPosedge;
  start.inject(0);

  final hwRng = <int>[];
  final hwII = <List<int>>[];
  var guard = 0;
  while (true) {
    final doneV = t.output('done').value;
    if (doneV.isValid && doneV.toInt() == 1) break;
    if (!doneV.isValid) {
      // ignore: avoid_print
      print('done went X at guard=$guard after ${hwRng.length} symbols');
      break;
    }
    await clk.nextPosedge;
    final sv = t.output('sym_valid').value;
    if (sv.isValid && sv.toInt() == 1) {
      final rv = t.output('rng').value;
      hwRng.add(rv.isValid ? rv.toInt() : -1);
    }
    final bv = t.output('block_valid').value;
    if (bv.isValid && bv.toInt() == 1) {
      final ii = t.output('blk_interintra').value;
      if (ii.isValid && ii.toInt() == 1) {
        final useWedge = t.output('blk_iiwedge').value.toInt();
        hwII.add([
          t.output('blk_r').value.toInt(),
          t.output('blk_c').value.toInt(),
          t.output('blk_bs').value.toInt(),
          t.output('blk_iimode').value.toInt(),
          useWedge,
          useWedge == 1 ? t.output('blk_iiwedgeidx').value.toInt() : 0,
        ]);
      }
    }
    if (++guard > 400000) fail('interintra frame decode timeout');
  }

  var firstDiff = -1;
  final nCmp = hwRng.length < gTrace.length ? hwRng.length : gTrace.length;
  for (var i = 0; i < nCmp; i++) {
    if (hwRng[i] != gTrace[i][4]) {
      firstDiff = i;
      break;
    }
  }
  if (firstDiff >= 0) {
    final g = gTrace[firstDiff];
    // ignore: avoid_print
    print(
      'FIRST DIVERGENCE at symbol $firstDiff (SW tag ${g[5]}): '
      'HW rng=${hwRng[firstDiff]} SW rngAfter=${g[4]} '
      '(SW sym=${g[3]}, nsyms=${g[2]}, tellBefore=${g[0]})',
    );
  }
  // ignore: avoid_print
  print(
    'frame $target: HW decoded ${hwRng.length} symbols; SW '
    '${gTrace.length}. In-sync through symbol '
    '${firstDiff < 0 ? nCmp - 1 : firstDiff - 1}.',
  );

  expect(firstDiff, equals(-1), reason: 'every od_ec symbol matches SW');
  expect(
    hwRng.length,
    equals(expSyms),
    reason: 'HW decodes all $expSyms symbols',
  );
  expect(hwRng.last, equals(expRng), reason: 'frame-end od_ec rng == $expRng');

  // Interintra blocks decoded by HW match SW exactly (flag/mode/wedge/idx).
  expect(hwII, equals(expII), reason: 'HW interintra blocks == SW');

  await Simulator.endSimulation();
}

/// Drive HarborIntraPred + HarborMaskBlend (with the smooth ramp or a
/// HarborWedgeMask) to blend an intra prediction over the inter block, and
/// return the HW blended luma block.
Future<List<int>> hwInterIntraBlend({
  required int iiMode,
  required int bs,
  required List<int> above,
  required List<int> left,
  required int aboveLeft,
  required List<int> inter,
  int? wedgeBSize,
  int? wedgeIdx,
}) async {
  final n = bs * bs;
  final pred = HarborIntraPred(bs: bs);
  final blend = HarborMaskBlend(width: bs, height: bs);
  final modeIn = Logic(name: 'mode', width: 4);
  final aboveIn = Logic(name: 'above', width: bs * 8);
  final leftIn = Logic(name: 'left', width: bs * 8);
  final alIn = Logic(name: 'al', width: 8);
  pred.input('mode').srcConnection! <= modeIn;
  pred.input('above').srcConnection! <= aboveIn;
  pred.input('left').srcConnection! <= leftIn;
  pred.input('above_left').srcConnection! <= alIn;

  final bIn = Logic(name: 'b', width: n * 8);
  final maskIn = Logic(name: 'mask', width: n * 7);
  // a = the HW intra prediction over the block, b = the inter prediction.
  blend.input('a').srcConnection! <= pred.output('pred');
  blend.input('b').srcConnection! <= bIn;
  blend.input('mask').srcConnection! <= maskIn;

  await pred.build();
  await blend.build();

  const modeMap = [0, 1, 2, 9]; // DC/V/H/SMOOTH AV1 PREDICTION_MODE
  BigInt pack8(List<int> v) {
    var acc = BigInt.zero;
    for (var i = 0; i < v.length; i++) {
      acc |= BigInt.from(v[i] & 0xFF) << (i * 8);
    }
    return acc;
  }

  // Mask: wedge (HarborWedgeMask codebook) or the smooth interintra ramp.
  final maskVals = wedgeBSize != null
      ? HarborWedgeMask.wedgeMask(wedgeBSize, wedgeIdx!, 0)
      : HarborMaskBlend.interIntraMask(InterIntraMode.values[iiMode], bs, bs);
  var mv = BigInt.zero;
  for (var i = 0; i < n; i++) {
    mv |= BigInt.from(maskVals[i] & 0x7F) << (i * 7);
  }

  // Pure combinational pipeline: put() propagates synchronously.
  modeIn.put(modeMap[iiMode]);
  aboveIn.put(pack8(above));
  leftIn.put(pack8(left));
  alIn.put(aboveLeft & 0xFF);
  bIn.put(pack8(inter));
  maskIn.put(mv);

  final outV = blend.output('out').value;
  final out = List<int>.filled(n, 0);
  for (var i = 0; i < n; i++) {
    out[i] = outV.getRange(i * 8, i * 8 + 8).toInt();
  }
  return out;
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test(
    'HarborInterFrameWalk: SMOOTH interintra frame (frame 2) sync vs SW',
    timeout: const Timeout(Duration(minutes: 40)),
    () async {
      await runInterIntraFrame(
        target: 2,
        expSyms: 406,
        expRng: 45750,
        maxBytes: 44,
        // Every tx size the frame's coeff decode actually uses (luma + chroma,
        // all planes). A missing size decodes that txb with the wrong coeff
        // engine. Because bypass symbols do not renormalize rng, such an error is
        // invisible until the next renormalizing symbol (here: block 17's skip).
        txCoeffSizes: const [0, 1, 2, 3, 5, 6, 7, 8, 13, 14],
        // r, c, bs, mode(V=1), useWedge(0), wedgeIdx(0).
        expII: const [
          [8, 10, 3, 1, 0, 0],
        ],
        cap: _cap2,
      );
    },
  );

  test(
    'HarborInterFrameWalk: WEDGE interintra frame (frame 9) sync vs SW',
    timeout: const Timeout(Duration(minutes: 60)),
    () async {
      await runInterIntraFrame(
        target: 9,
        expSyms: 488,
        expRng: 40756,
        maxBytes: 58,
        txCoeffSizes: const [1, 2, 5, 6, 7, 8, 13],
        expII: const [
          [4, 6, 4, 1, 1, 8], // II_V, wedge idx 8
          [4, 8, 3, 3, 1, 4], // II_SMOOTH, wedge idx 4
          [4, 10, 3, 1, 0, 0], // II_V, no wedge
        ],
        cap: _cap9,
      );
    },
  );

  test(
    'interintra predict+blend composition bit-exact vs SW (smooth + wedge)',
    () async {
      final rng = Random(20260724);
      var ci = 0;
      // Smooth ramp for each II mode on 8x8 and 16x16 luma blocks.
      for (final bs in [8, 16]) {
        final above = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final left = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final corner = rng.nextInt(256);
        final inter = [for (var i = 0; i < bs * bs; i++) rng.nextInt(256)];
        for (var mode = 0; mode < 4; mode++) {
          final hw = await hwInterIntraBlend(
            iiMode: mode,
            bs: bs,
            above: above,
            left: left,
            aboveLeft: corner,
            inter: inter,
          );
          final swb = _goldenComp[ci++];
          expect(
            hw,
            equals(swb),
            reason: 'smooth interintra bs=$bs mode=$mode bit-exact vs SW',
          );
          await Simulator.reset();
        }
      }

      // Wedge mask on an 8x8 (BLOCK_8X8=3) and 16x16 (BLOCK_16X16=6) luma block,
      // II_V mode (mode is irrelevant to the wedge mask itself, the intra pred
      // mode still varies the intra samples).
      for (final entry in const [
        [8, 3, 8], // bs, bSize BLOCK_8X8, wedge index
        [16, 6, 4], // bs, bSize BLOCK_16X16, wedge index
      ]) {
        final bs = entry[0], bSize = entry[1], widx = entry[2];
        final above = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final left = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final corner = rng.nextInt(256);
        final inter = [for (var i = 0; i < bs * bs; i++) rng.nextInt(256)];
        for (var mode = 0; mode < 4; mode++) {
          final hw = await hwInterIntraBlend(
            iiMode: mode,
            bs: bs,
            above: above,
            left: left,
            aboveLeft: corner,
            inter: inter,
            wedgeBSize: bSize,
            wedgeIdx: widx,
          );
          final swb = _goldenComp[ci++];
          expect(
            hw,
            equals(swb),
            reason: 'wedge interintra bs=$bs idx=$widx mode=$mode vs SW',
          );
          await Simulator.reset();
        }
      }
    },
  );
}
